/**
 * Harness tree rows: the chats of a project grouped by the TICKET BRANCH.
 *
 * The branch is saved in the chat model by the backend (`Chat.branch`) when the
 * ticket is created, so the tree groups by a value that was recorded, never
 * guessed from the checkout. A chat without it lands in the "Unknown" node.
 *
 * The rows are sorted with the checkout's branch first, the other branches
 * alphabetically and "Unknown" last.
 *
 * Kept out of the SFC so the grouping (and the Unknown node) is unit tested:
 * `cd client && node --test tests/harnessTree.test.mjs`.
 */

/** Label of the node holding the chats without a recorded ticket branch. */
export const UNKNOWN_BRANCH = 'Unknown'
/** Group key of that node (never collides with a real branch name). */
export const UNKNOWN_BRANCH_KEY = '__unknown__'

/**
 * Group key of a session: its ticket branch, or the unknown marker.
 *
 * @param {object} session - Session summary from the harness API.
 * @returns {string} The branch name or :data:`UNKNOWN_BRANCH_KEY`.
 */
export function branchKey(session) {
  return String(session?.branch || '').trim() || UNKNOWN_BRANCH_KEY
}

/**
 * Build the flat row list of the sidebar tree.
 *
 * @param {Array<object>} [sessions] - Session summaries.
 * @param {object} [options]
 * @param {string} [options.currentBranch] - Checked out branch (sorted first).
 * @param {string} [options.search] - Term matched against name/description/preview/model.
 * @param {string[]} [options.collapsed] - Branch keys rendered collapsed.
 * @returns {Array<object>} A branch header row followed by its session rows.
 */
export function harnessTreeRows(
  sessions = [],
  { currentBranch = '', search = '', collapsed = [] } = {}
) {
  const term = String(search || '').trim().toLowerCase()
  const matches = session => [
    session?.name,
    session?.description,
    session?.preview,
    session?.model
  ].some(value => String(value || '').toLowerCase().includes(term))

  const groups = new Map()
  for (const session of sessions || []) {
    const key = branchKey(session)
    if (!groups.has(key)) groups.set(key, [])
    groups.get(key).push(session)
  }

  const active = String(currentBranch || '').trim()
  const order = [...groups.keys()].sort((a, b) => {
    if (a === active) return -1
    if (b === active) return 1
    // Tickets without a ticket branch are last: the "Unknown" node.
    if (a === UNKNOWN_BRANCH_KEY) return 1
    if (b === UNKNOWN_BRANCH_KEY) return -1
    return a.localeCompare(b)
  })

  const rows = []
  for (const key of order) {
    const all = groups.get(key)
    const visible = term ? all.filter(matches) : all
    if (term && !visible.length) continue
    const isCollapsed = (collapsed || []).includes(key)
    const unknown = key === UNKNOWN_BRANCH_KEY
    rows.push({
      session_id: `branch:${key}`,
      __branchHeader: true,
      __branchKey: key,
      // No branch name on the unknown node: diff/merge are not offered there.
      __branch: unknown ? '' : key,
      __branchLabel: unknown ? UNKNOWN_BRANCH : key,
      __branchUnknown: unknown,
      __branchCount: all.length,
      __branchRunning: all.filter(item => item.phase === 'running').length,
      __branchCurrent: !unknown && key === active,
      __branchCollapsed: isCollapsed
    })
    if (isCollapsed) continue
    for (const session of visible) rows.push({ ...session, __branchKey: key })
  }
  return rows
}

/**
 * Harness tree grouping: chats are grouped by the ticket branch SAVED in the
 * chat model, and the chats without one land in the "Unknown" node.
 *
 * Run with: `cd client && node --test tests/harnessTree.test.mjs`
 */
import assert from 'node:assert/strict'
import test from 'node:test'

import {
  UNKNOWN_BRANCH,
  UNKNOWN_BRANCH_KEY,
  branchKey,
  harnessTreeRows
} from '../src/utils/harnessTree.js'

const session = (id, branch, extra = {}) => ({
  session_id: id,
  name: `chat ${id}`,
  branch,
  phase: 'idle',
  ...extra
})

test('branchKey uses the recorded branch and falls back to unknown', () => {
  assert.equal(branchKey({ branch: 'feature/a' }), 'feature/a')
  assert.equal(branchKey({ branch: '  ' }), UNKNOWN_BRANCH_KEY)
  assert.equal(branchKey({}), UNKNOWN_BRANCH_KEY)
  assert.equal(branchKey(null), UNKNOWN_BRANCH_KEY)
})

test('chats are grouped by the ticket branch saved in the chat model', () => {
  const rows = harnessTreeRows([
    session('1', 'feature/a'),
    session('2', 'feature/b'),
    session('3', 'feature/a')
  ])

  const headers = rows.filter(row => row.__branchHeader)
  assert.deepEqual(headers.map(row => row.__branchLabel), ['feature/a', 'feature/b'])
  assert.deepEqual(headers.map(row => row.__branchCount), [2, 1])
  assert.deepEqual(
    rows.filter(row => !row.__branchHeader).map(row => [row.session_id, row.__branchKey]),
    [['1', 'feature/a'], ['3', 'feature/a'], ['2', 'feature/b']]
  )
})

test('chats without a branch are grouped in the Unknown node, sorted last', () => {
  const rows = harnessTreeRows([
    session('1', ''),
    session('2', 'feature/a'),
    session('3')
  ])

  const headers = rows.filter(row => row.__branchHeader)
  assert.deepEqual(headers.map(row => row.__branchLabel), ['feature/a', UNKNOWN_BRANCH])
  const unknown = headers[headers.length - 1]
  assert.equal(unknown.__branchUnknown, true)
  // No branch name: the branch menu (diff/merge/archive by branch) is not offered.
  assert.equal(unknown.__branch, '')
  assert.equal(unknown.__branchCount, 2)
  assert.deepEqual(
    rows.filter(row => row.__branchKey === UNKNOWN_BRANCH_KEY).map(row => row.session_id),
    ['1', '3']
  )
})

test('the checked out branch is sorted first and marked as current', () => {
  const rows = harnessTreeRows(
    [session('1', 'aaa'), session('2', 'zzz'), session('3', '')],
    { currentBranch: 'zzz' }
  )

  const headers = rows.filter(row => row.__branchHeader)
  assert.deepEqual(headers.map(row => row.__branchLabel), ['zzz', 'aaa', UNKNOWN_BRANCH])
  assert.deepEqual(headers.map(row => row.__branchCurrent), [true, false, false])
})

test('a collapsed branch renders its header only', () => {
  const rows = harnessTreeRows(
    [session('1', 'feature/a'), session('2', 'feature/b')],
    { collapsed: ['feature/a'] }
  )

  assert.deepEqual(
    rows.map(row => row.__branchHeader ? `header:${row.__branchKey}` : row.session_id),
    ['header:feature/a', 'header:feature/b', '2']
  )
})

test('search filters sessions and drops the empty branches', () => {
  const rows = harnessTreeRows(
    [
      session('1', 'feature/a', { name: 'Fix the export' }),
      session('2', 'feature/b', { name: 'Add docs' })
    ],
    { search: 'export' }
  )

  assert.deepEqual(rows.map(row => row.session_id), ['branch:feature/a', '1'])
})

test('running sessions are counted per branch', () => {
  const rows = harnessTreeRows([
    session('1', 'feature/a', { phase: 'running' }),
    session('2', 'feature/a')
  ])

  const [header] = rows
  assert.equal(header.__branchHeader, true)
  assert.equal(header.__branchRunning, 1)
})

